import pickle,numpy as np
from rdkit import Chem
m=pickle.load(open('mol.pkl','rb')); x=m.GetConformer().GetPositions()
for idx in [0,26,1,9,49]:
 a=m.GetAtomWithIdx(idx); print(idx,a.GetSymbol(),x[idx]); print([(n.GetIdx(),n.GetSymbol(),np.round(x[n.GetIdx()],2).tolist()) for n in a.GetNeighbors()])
