# plot structure with indices
import matplotlib;matplotlib.use('Agg')
import matplotlib.pyplot as plt
fig=plt.figure(figsize=(11,9)); ax=fig.add_subplot(111,projection='3d')
colors={'C':'gray','N':'blue','O':'red','B':'pink','H':'lightgray','Ni':'green'}
for a in m.GetAtoms():
 i=a.GetIdx();ax.scatter(*x[i],c=colors[a.GetSymbol()],s=65 if a.GetSymbol()!='H' else 10)
 if a.GetSymbol()!='H':ax.text(*x[i],str(i),size=8)
for b in m.GetBonds():
 p=x[[b.GetBeginAtomIdx(),b.GetEndAtomIdx()]];ax.plot(*p.T,c='black',lw=1)
ax.set_box_aspect(np.ptp(x,axis=0));ax.view_init(70,-70);plt.tight_layout();plt.savefig('structure.png',dpi=140)
